3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two
7	 * digits of the registration date's fiscal year (see {@link FiscalYears}), e.g. 'SYD-SMI-0007-M26'.
8	 * The number combines the owner's assigned customer code with the fiscal year, so it is only
9	 * available once both the code and the registration date have been set.
10	 */
11	public final class MembershipNumbers {
12	
13	    private MembershipNumbers() {
14	    }
15	
16	    /**
17	     * Return the owner's membership number, or null when either the customer code or the
18	     * registration date is absent.
19	     */
20	    public static String of(Owner owner) {
21	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
22	            return null;
23	        }
24	        return String.format("%s-M%02d", owner.getCustomerCode(),
25	                FiscalYears.startYear(owner.getRegistrationDate()) % 100);
26	    }
27	}
