1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Derives an owner's market segment '&lt;TIER&gt;_&lt;AREA&gt;' from their membership level and
5	 * locality. TIER is PREMIUM at membership level {@link #PREMIUM_LEVEL} or above, otherwise
6	 * STANDARD. AREA is METRO for a known region (a resolved locality), otherwise REGIONAL.
7	 */
8	public enum OwnerSegment {
9	
10	    PREMIUM_METRO, PREMIUM_REGIONAL, STANDARD_METRO, STANDARD_REGIONAL;
11	
12	    /** Membership level (inclusive) at and above which an owner is PREMIUM. */
13	    public static final int PREMIUM_LEVEL = 3;
14	
15	    /**
16	     * Return the segment for an owner with the given {@code membershipLevel} and {@code locality}
17	     * (a canonical region, or {@link CityRegions#UNKNOWN} when the region is not known).
18	     */
19	    public static OwnerSegment of(Integer membershipLevel, String locality) {
20	        boolean premium = membershipLevel != null && membershipLevel >= PREMIUM_LEVEL;
21	        boolean metro = !CityRegions.UNKNOWN.equals(locality);
22	        if (premium) {
23	            return metro ? PREMIUM_METRO : PREMIUM_REGIONAL;
24	        }
25	        return metro ? STANDARD_METRO : STANDARD_REGIONAL;
26	    }
27	}
