1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * E.164 telephone knowledge shared across the application: the country calling codes it
7	 * recognizes, the national-number length each requires, and human-readable display formatting.
8	 * <p>
9	 * This is deliberately separate from the lenient canonicalization that turns a raw request
10	 * value into E.164 (an owner-pipeline concern): canonicalization stays lenient so numbers can
11	 * be compared against existing owners, while the create request is additionally held to the
12	 * stricter, country-specific national length checked here.
13	 */
14	public final class Telephones {
15	
16	    /** Country calling code -> required national-number length. Matched longest-code-first,
17	     *  so a code that is a prefix of another still resolves to the more specific rule. */
18	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of(
19	            "61", 9,
20	            "1", 10);
21	
22	    private Telephones() {
23	    }
24	
25	    /**
26	     * The longest recognized country calling code that prefixes the digits of {@code e164}
27	     * (a '+' followed by digits), or {@code null} when no configured code matches or the
28	     * argument is not in E.164 form.
29	     */
30	    public static String countryCode(String e164) {
31	        if (e164 == null || !e164.startsWith("+")) {
32	            return null;
33	        }
34	        String digits = e164.substring(1);
35	        String best = null;
36	        for (String code : NATIONAL_DIGITS.keySet()) {
37	            if (digits.startsWith(code) && (best == null || code.length() > best.length())) {
38	                best = code;
39	            }
40	        }
41	        return best;
42	    }
43	
44	    /**
45	     * Returns {@code true} when {@code e164} (a '+' followed by digits) carries the
46	     * national-number length required for its country code, or when its country code has no
47	     * configured length. A {@code null} or non-E.164 argument returns {@code false}.
48	     */
49	    public static boolean isNationalLengthValid(String e164) {
50	        String code = countryCode(e164);
51	        if (code == null) {
52	            return e164 != null && e164.startsWith("+");
53	        }
54	        String national = e164.substring(1 + code.length());
55	        return national.length() == NATIONAL_DIGITS.get(code);
56	    }
57	
58	    /**
59	     * Format a stored E.164 telephone for humans as '+&lt;countryCode&gt; &lt;national digits
60	     * grouped in threes&gt;' (e.g. '+61412345678' becomes '+61 412 345 678'). When the country
61	     * code is not recognized, every digit after the '+' is grouped as the national part.
62	     * Returns {@code null} for a {@code null} or non-E.164 argument.
63	     */
64	    public static String forDisplay(String e164) {
65	        if (e164 == null || !e164.startsWith("+")) {
66	            return null;
67	        }
68	        String code = countryCode(e164);
69	        String national = e164.substring(code == null ? 1 : 1 + code.length());
70	        String prefix = code == null ? "+" : "+" + code + " ";
71	        return prefix + groupInThrees(national);
72	    }
73	
74	    /** Groups {@code digits} into space-separated runs of three from the left. */
75	    private static String groupInThrees(String digits) {
76	        StringBuilder grouped = new StringBuilder();
77	        for (int i = 0; i < digits.length(); i++) {
78	            if (i > 0 && i % 3 == 0) {
79	                grouped.append(' ');
80	            }
81	            grouped.append(digits.charAt(i));
82	        }
83	        return grouped.toString();
84	    }
85	}
