1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.CustomerCode;
10	import org.springframework.samples.petclinic.util.Postcodes;
11	
12	/**
13	 * Assigns the owner's customer code before it is saved. The code is the region-and-hash
14	 * identity {@code <REGION>-<HASH8>} (see {@link CustomerCode}): {@code REGION} is the region
15	 * derived from the owner's postcode and {@code HASH8} the first eight upper-case hex characters
16	 * of the SHA-256 digest over the normalized telephone and last name. Should that code collide
17	 * with an existing owner's, it is {@link CustomerCode#deduplicate de-duplicated} with a
18	 * {@code -<n>} suffix so distinct owners always receive distinct codes. Runs after
19	 * {@link NormalizeOwnerTelephone} has put the telephone in E.164 form and {@link BuildOwner}
20	 * has produced the entity, so the hash sees the normalized value; mutates the built owner in
21	 * place.
22	 */
23	public class AssignCustomerCode {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String region = Postcodes.regionCode(owner.getPostcode());
27	        String customerCode = CustomerCode.of(region, owner.getTelephone(), owner.getLastName());
28	        owner.setCustomerCode(CustomerCode.deduplicate(customerCode, existingCodes(ownerRepository)));
29	    }
30	
31	    private static Set<String> existingCodes(OwnerRepository ownerRepository) {
32	        Set<String> codes = new HashSet<>();
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (existing.getCustomerCode() != null) {
35	                codes.add(existing.getCustomerCode());
36	            }
37	        }
38	        return codes;
39	    }
40	}
