6	/**
7	 * Assigns the owner's derived identity key before it is saved, so the value returned in the
8	 * response matches the key used for duplicate detection. Derived via {@link OwnerIdentity} from
9	 * the owner's normalized telephone, email and last-name Soundex code. Runs after
10	 * {@link BuildOwner} has produced the entity and before {@link SaveOwner} persists it, mutating
11	 * the built owner in place.
12	 */
13	public class AssignIdentityKey {
14	
15	    public void service(@Val Owner owner) {
16	        owner.setIdentityKey(OwnerIdentity.of(owner));
17	    }
18	}
