1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.util.Sha256;
8	
9	/**
10	 * Canonical identity of an owner for duplicate detection. All duplicate detection is
11	 * consolidated into this single derived key: the lower-case hex SHA-256 digest of
12	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners are
13	 * duplicates only when their whole keys are equal.
14	 *
15	 * <p>A person is individuated by their telephone, email and how their last name sounds: a
16	 * re-registration reusing all three is a duplicate regardless of address, while two members of
17	 * one household with different telephones have different keys and are both allowed (the softer
18	 * sound-alike-plus-postcode collision is only flagged, see {@link FlagPossibleDuplicate}).
19	 *
20	 * <p>Telephone is canonicalized with {@link TelephoneNormalizer#toE164(String)}, email is
21	 * lower-cased and the last name is reduced to its {@link Soundex} code, so the key is computed
22	 * identically for an incoming request and an already-stored owner regardless of incidental
23	 * formatting differences.
24	 */
25	final class OwnerIdentity {
26	
27	    private OwnerIdentity() {
28	    }
29	
30	    /** Identity key of a create request. */
31	    static String of(OwnerFieldsDto request) {
32	        return of(request.getTelephone(), request.getEmail(), request.getLastName());
33	    }
34	
35	    /** Identity key of an existing owner. */
36	    static String of(Owner owner) {
37	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
38	    }
39	
40	    private static String of(String telephone, String email, String lastName) {
41	        String normalizedTelephone = TelephoneNormalizer.toE164(telephone);
42	        String normalizedEmail = (email == null) ? "" : email.trim().toLowerCase(Locale.ROOT);
43	        String raw = (normalizedTelephone == null ? "" : normalizedTelephone)
44	                + '|' + normalizedEmail + '|' + Soundex.encode(lastName);
45	        return Sha256.hex(raw);
46	    }
47	}
