1	package org.springframework.samples.petclinic.rest.audit;
2	
3	import java.time.LocalDate;
4	
5	import tools.jackson.databind.json.JsonMapper;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.util.MembershipLevels;
9	
10	/**
11	 * Immutable structured audit event for a newly created owner, rendered as a single-line JSON
12	 * object {@code {seq, ownerId, customerCode, membershipLevel, event}}.
13	 *
14	 * <p>The event carries the owner's current primary identifier. Today that identifier is the
15	 * customer code, so it is read in {@link #of} alone: when the primary identifier is later
16	 * unified into a member id, only that one place changes and the event carries the member id
17	 * instead.
18	 */
19	public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel,
20	        String event) {
21	
22	    /** The {@code event} discriminator carried by every owner-creation event. */
23	    public static final String OWNER_CREATED = "OWNER_CREATED";
24	
25	    private static final JsonMapper JSON = JsonMapper.builder().build();
26	
27	    /**
28	     * Build the event for {@code owner} (already persisted, so its id is set) at sequence number
29	     * {@code seq}, deriving the effective membership level as at {@code asOf}. The owner's primary
30	     * identifier is read here, in one place.
31	     */
32	    public static OwnerCreatedEvent of(long seq, Owner owner, LocalDate asOf) {
33	        return new OwnerCreatedEvent(seq, owner.getId(), owner.getCustomerCode(),
34	                MembershipLevels.levelOf(owner, asOf), OWNER_CREATED);
35	    }
36	
37	    /** Render this event as a compact single-line JSON object. */
38	    public String toJson() {
39	        return JSON.writeValueAsString(this);
40	    }
41	}
