1	package org.springframework.samples.petclinic.rest.audit;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.stereotype.Component;
6	
7	/**
8	 * Source of the monotonically increasing sequence number carried by each
9	 * {@link OwnerCreatedEvent}. A single shared counter across all owner creations for the life of
10	 * the application, so successive creates receive strictly increasing sequence numbers.
11	 */
12	@Component
13	public class OwnerEventSequence {
14	
15	    private final AtomicLong counter = new AtomicLong();
16	
17	    /** The next sequence number, starting at 1 and increasing by one on each call. */
18	    public long next() {
19	        return this.counter.incrementAndGet();
20	    }
21	}
