1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import java.time.LocalDate;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.audit.OwnerCreatedEvent;
11	import org.springframework.samples.petclinic.rest.audit.OwnerEventSequence;
12	import org.springframework.samples.petclinic.util.MembershipLevels;
13	import org.springframework.samples.petclinic.util.MembershipNumbers;
14	
15	/**
16	 * Emits the audit trail for a newly created owner. Runs after {@link SaveOwner} has persisted
17	 * the entity, so the generated id is available. On the dedicated {@code AUDIT} logger it emits
18	 * both a human-readable line (owner id, assigned customer code, effective registration date,
19	 * derived membership points, level and number) and an immutable structured
20	 * {@link OwnerCreatedEvent}, stamped with the next sequence number. Purely a side-effect step;
21	 * it leaves the owner unchanged for the responder.
22	 */
23	public class AuditOwnerCreated {
24	
25	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
26	
27	    public void service(@Val Owner owner, OwnerEventSequence sequence) {
28	        LocalDate asOf = LocalDate.now();
29	        int points = MembershipLevels.pointsOf(owner, asOf);
30	        AUDIT.info(
31	                "Owner created: id={} customerCode={} registrationDate={} membershipPoints={} membershipLevel={} membershipNumber={}",
32	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
33	                points, MembershipLevels.levelOf(owner, asOf), MembershipNumbers.of(owner));
34	        AUDIT.info(OwnerCreatedEvent.of(sequence.next(), owner, asOf).toJson());
35	    }
36	}
