306	    public void setPets(List<Pet> pets) {
307	        this.pets = new HashSet<>(pets);
308	    }
309	
310	    public void addPet(Pet pet) {
311	        getPetsInternal().add(pet);
312	        pet.setOwner(this);
313	    }
314	
315	    /**
316	     * Return the Pet with the given name, or null if none found for this Owner.
317	     *
318	     * @param name to test
319	     * @return true if pet name is already in use
320	     */
321	    public Pet getPet(String name) {
322	        return getPet(name, false);
323	    }
324	
325	    /**
326	     * Return the Pet with the given name, or null if none found for this Owner.
327	     *
328	     * @param name to test
329	     * @return true if pet name is already in use
330	     */
331	    public Pet getPet(String name, boolean ignoreNew) {
332	        name = name.toLowerCase();
333	        for (Pet pet : getPetsInternal()) {
334	            if (!ignoreNew || !pet.isNew()) {
335	                String compName = pet.getName();
336	                compName = compName.toLowerCase();
337	                if (compName.equals(name)) {
338	                    return pet;
339	                }
340	            }
341	        }
342	        return null;
343	    }
344	
345	    public Pet getPet(Integer petId) {
346	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
347	    }
348	
349	    @Override
350	    public String toString() {
351	        return new ToStringCreator(this)
352	
353	            .append("id", this.getId())
354	            .append("new", this.isNew())
355	            .append("lastName", this.getLastName())
356	            .append("firstName", this.getFirstName())
357	            .append("address", this.address)
358	            .append("city", this.city)
359	            .append("telephone", this.telephone)
360	            .append("email", this.email)
361	            .toString();
362	    }
363	}
